import {renderStory,renderStorySummary} from './story-ui.js';
import {renderCharacterOverview,renderBuildSummary} from './character-sheet.js';
import {renderEncounterRecord,renderEncounterOutcome} from './battle-report.js';
import {renderWorldHub,renderSocialDrawer} from './world-ui.js';
import * as G from './engine.js';
import * as C from './characters.js';
import * as M from './market-ui.js';
import {MENU_ICONS} from './menu-icons.js';
import {UI_ICONS} from './ui-icons.js';
import {renderEnemyArt} from './enemy-art.js';
import {renderItemArt,renderServiceArt} from './item-art.js';
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='crown-calamity-v1',ROSTER_KEY='crown-calamity-roster-v1';let saveOK=true,saveRaw=null,rosterRaw=null;try{saveRaw=localStorage.getItem(KEY);rosterRaw=localStorage.getItem(ROSTER_KEY);}catch{saveOK=false;}
let roster=C.loadRoster(rosterRaw,saveRaw)||C.loadRoster(null,saveRaw)||C.emptyRoster(),state=C.activeCharacter(roster),firstRun=!state,view='hunt',huntTab='hunts',bagTab='gear',shopMode='buy',vendorId='weaponsmith',charTab='overview',worldTab='world',socialOpen=false,socialTab='chat',toastTimer,actionDelayTimer;if(!state)state=G.fresh();
function icon(k,cls=''){const path=Object.hasOwn(MENU_ICONS,k)?MENU_ICONS[k]:Object.hasOwn(UI_ICONS,k)?UI_ICONS[k]:UI_ICONS.spark;return `<svg class="icon menu-icon pixel-glyph ${cls}" viewBox="0 0 24 24" fill="currentColor" shape-rendering="crispEdges" aria-hidden="true" focusable="false">${path}</svg>`;}
function enemyArt(e){return renderEnemyArt(e,{animated:!!state.fight&&state.fight.enemy===e.id});}
function itemArt(item,size='small'){return renderItemArt(typeof item==='string'?item:item?.id,{size});}
function save(){if(firstRun||!roster.activeId)return;try{C.saveActiveCharacter(roster,state);localStorage.setItem(ROSTER_KEY,JSON.stringify(roster));localStorage.setItem(KEY,JSON.stringify(state));saveOK=true;}catch{saveOK=false;}}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function btn(action,text,cls='',disabled=false){const glyph={compare:'compare','buy-preview':'buy','sell-preview':'sell',upgrade:'upgrade','affix-menu':'reforge',exchange:'materials','character-manager':'characters',identity:'characters',respec:'attributes',export:'save',import:'save','open-gear':'gear','open-shop':'market','nav-abilities':'abilities'}[action.split(':')[0]];return `<button data-action="${esc(action)}" class="${cls}" ${disabled?'disabled':''}>${glyph&&!text.includes('<svg')?icon(glyph):''}${text}</button>`;}
function resolved(id){return G.resolveItem(state,id);}
function itemIcon(i){return ({weapon:i.focus?'staff':'sword',offhand:i.armor?'shield':'spark',head:'crown',body:'coat',hands:'shield',feet:'rest',accessory:'spark',accessory2:'spark',relic:'scroll'})[i.slot]||'spark';}
function nav(){return [['hunt','The adventure','hunt'],['story','Story & contracts','story'],['character','Character','character'],['bag','Satchel','bag'],['market','Quay market','market'],['journal','Chronicle','journal'],['world','World & community','guide'],['guide','Field guide','guide']];}
function resources(){const t=G.totals(state);return `<div class="resources" aria-label="Character resources">${[['hp','Health','heart'],['mp','Mana','mana'],['sp','Stamina','bolt']].map(([k,label,ic])=>`<div class="resource ${k}"><label><span class="resource-name">${icon(ic)} ${label.toUpperCase()}</span><span class="${k==='hp'&&state.hp<t.hp*.25?'health-warning':''}">${state[k]} <span class="muted">/ ${t[k]}</span></span></label><div class="bar" role="meter" aria-label="${label}" aria-valuemin="0" aria-valuemax="${t[k]}" aria-valuenow="${state[k]}"><i style="width:${Math.max(0,state[k]/t[k]*100)}%"></i></div></div>`).join('')}<div class="resource-recovery">${btn('rest',`${icon('rest')} Rest at the Quay`,'resource-rest',!!state.fight||!!state.delve)}<small>${state.delve?'Available after leaving the Works.':state.fight?'Available after this encounter.':'Fully restore Health, Mana, and Stamina.'}</small></div></div>`;}
function shell(body,title,subtitle,eyebrow='CHAPTER I · BRACKEN QUAY'){const combat=!!state.fight&&view==='hunt';return `<div class="shell bursar-shell"><aside class="sidebar"><div class="brand">${icon('crown')}<div class="wordmark">CROWN <span>&</span> CALAMITY</div></div><div class="nav-label">YOUR ADVENTURE</div><nav aria-label="Main navigation">${nav().map(([v,n,i])=>btn('nav:'+v,`${icon(i)}${n}${v==='character'&&state.points?`<span class="count">${state.points}</span>`:''}`,`nav-link ${view===v?'active':''}`)).join('')}</nav><div class="sidebar-footer"><div class="location">${icon('pin')} Bracken Quay</div><p>The water is rising.<br>The paperwork is not helping.</p>${btn('rest',`${icon('rest')} Rest at the Quay`,'subtle',!!state.fight||!!state.delve)}<div class="version">SOLO PROTOTYPE · v0.8.0</div></div></aside><div class="page page--${view} ${combat?'in-combat':''}"><header class="topbar interface-header"><div class="bursar-interface"><img src="assets/hud/bursar-sigil.png" alt=""><span><strong>B.U.R.S.A.R.</strong><small>ADVENTURER INTERFACE · LOCAL ARCHIVE</small></span></div><div class="place">${icon('pin')} <span>Bracken Quay</span> <span>/</span><span>${{hunt:'The Lower Canals',story:'Story contracts',character:'Character record',bag:'Personal effects',market:'Quay market',journal:'Adventure chronicle',guide:'Field guide',world:'World & community'}[view]}</span></div><div class="topbar-right"><button id="social-toggle" class="social-toggle" data-action="social-open:chat" aria-label="Open community drawer" aria-controls="social-drawer" aria-expanded="${socialOpen}">${icon('journal')}<span>Community</span></button><span class="save-label"><i class="save-dot"></i>${saveOK?'Local archive · saved on this browser':'Local archive · saving unavailable'}</span><span class="coins">${icon('coin')} ${state.coins.toLocaleString()}</span><button data-action="nav:character" class="identity-button" aria-label="Open character sheet"><span class="identity-name">${esc(state.name)}</span><span class="level-box" title="Level ${state.level}">${state.level}</span></button></div></header><main class="content" id="main"><div class="page-title"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${subtitle}</p></div><span class="chapter-seal"><i></i> A PROVISIONAL ADVENTURER</span></div>${!saveOK?'<div class="error-banner">Browser saving is unavailable. Export a save from the Field Guide to keep your progress.</div>':''}${state.fight&&view!=='hunt'?`<div class="point-notice">An encounter is in progress. ${btn('nav:hunt','Return to encounter →')}</div>`:''}${resources()}${body}</main><footer class="footer"><span>CROWN & CALAMITY <span class="muted">/</span> AN ORIGINAL LITRPG</span><span>One tap. One exchange. Your next chapter.</span></footer></div><nav class="mobile-nav" aria-label="Mobile navigation">${nav().filter(([v])=>!['guide','world'].includes(v)).map(([v,n,i])=>btn('nav:'+v,`${icon(i)}<span>${{hunt:'Adventure',story:'Story',character:'Character',bag:'Satchel',market:'Market',journal:'Records',guide:'Guide'}[v]}</span>${v==='character'&&state.points?'<span class="badge">!</span>':''}`,view===v||(['guide','world'].includes(view)&&v==='journal')?'active':'')).join('')}</nav>${renderSocialDrawer({tab:socialTab,open:socialOpen})}</div>`;}
function titlePanel(label,body,cls=''){return `<section class="panel ${cls}"><div class="panel-label">${label}</div>${body}</section>`;}
function questPanel(){return renderStorySummary(state);}
const SLOT_ORDER=['weapon','offhand','head','body','hands','feet','accessory','accessory2','relic'];
const SLOT_LABELS={weapon:'Weapon',offhand:'Offhand',head:'Head',body:'Body',hands:'Hands',feet:'Feet',accessory:'Accessory',accessory2:'Second accessory',relic:'Relic'};
function equippedSlots(){return SLOT_ORDER.map(slot=>{const id=state.gear?.[slot],i=id?resolved(id):null,twoHanded=slot==='offhand'&&resolved(state.gear?.weapon)?.twoHanded,label=SLOT_LABELS[slot]||G.SLOTS?.[slot]||slot,value=i?.name||(twoHanded?`Occupied by ${resolved(state.gear.weapon).name}`:'Empty');return `<div class="equipment-slot-row"><button data-action="slot:${slot}" class="slot-list-open" aria-label="${esc(label)} slot: ${esc(value)}. Review slot contents"><span class="slot-name">${esc(label)}</span>${i?itemArt(i):''}<span class="slot-equipped">${i?`<strong>${esc(i.name)}</strong><small>${itemStats(i).map(esc).join(' · ')||esc(i.desc)}</small>`:`<span class="empty-slot-label">${esc(value)}</span>`}</span></button>${i?btn('unequip-slot:'+slot,'Unequip','subtle tiny slot-unequip',!!state.fight||!!state.delve||!!G.unequipReason(state,slot)):''}</div>`;}).join('');}
function gearDiagram(){return `<div class="gear-diagram" role="group" aria-label="Equipment slots arranged around a generic body outline">${SLOT_ORDER.map(slot=>{const id=state.gear?.[slot],i=id?resolved(id):null,twoHanded=slot==='offhand'&&resolved(state.gear?.weapon)?.twoHanded,label=SLOT_LABELS[slot]||G.SLOTS?.[slot]||slot,value=i?.name||(twoHanded?`Occupied by ${resolved(state.gear.weapon).name}`:'Empty');return `<button type="button" class="gear-slot-card slot-${slot} ${i?'filled':'empty'}" data-action="slot:${slot}" aria-label="${esc(label)} slot. ${esc(value)}. Activate to review or change"><span class="gear-slot-label">${esc(label)}</span>${i?itemArt(i):icon(({weapon:'sword',offhand:'shield',head:'crown',body:'coat',hands:'shield',feet:'rest',accessory:'spark',accessory2:'spark',relic:'scroll'})[slot])}<strong>${esc(value)}</strong><small>${i?itemStats(i).map(esc).join(' · ')||esc(i.desc):twoHanded?'Two-handed weapon occupies offhand':'Tap to view compatible gear'}</small></button>`;}).join('')}<div class="gear-figure" aria-hidden="true"><svg viewBox="0 0 120 280" focusable="false"><path d="M44 10h32v32H44zM52 42v14h16V42M40 56H28v16h-8v48h16V80h8v64h32V80h8v40h16V72h-8V56H80M44 144v48h-4v64H28v16h28v-80h8v80h28v-16H80v-64h-4v-48M44 56h32M44 104h32"/></svg><span>Equipment</span></div></div>`;}
function equipmentPanel(){return `<section class="panel equipment-panel"><div class="panel-label">YOUR EQUIPMENT · SELECT ANY SLOT</div>${gearDiagram()}<div class="equipment-list"><h3>Equipment list</h3><p class="tiny muted">Screen-reader and keyboard friendly slot list. Select a slot to compare or change what is equipped.</p>${equippedSlots()}</div></section>`;}
function buildPanel(){return renderBuildSummary(state);}
function rightSide(){return `<aside class="side-column">${questPanel()}${buildPanel()}<section class="panel quote"><span class="quote-mark">“</span><p>The canal is full of opportunities. Most of them have teeth.</p><footer>B.U.R.S.A.R. · ADVENTURER SERVICES</footer></section></aside>`;}
function pointNotice(){return state.points?`<div class="point-notice"><span>${icon('spark')} Level ${state.level} · <strong>${state.points} attribute point${state.points===1?'':'s'}</strong> to spend.</span>${btn('nav:character','Shape your build →')}</div>`:'';}
function hub(){const q=G.QUESTS[state.quest];return `<div class="hero"><div class="hero-top"><span class="eyebrow">BRACKEN QUAY · DISTRICT 01</span><span class="region-pill">HUNTING GROUNDS</span></div><div class="eyebrow">WELCOME TO THE LOWER CANALS</div><h2>An honest day’s calamity.</h2><p>The town stays dry. Something below it doesn’t like that arrangement. Take a contract. Make a name. Mind the teeth.</p><div class="hero-footer"><small>${icon('leaf')} Every adventure starts with a small problem.</small>${G.storyState(state).stage===0?btn('nav:story','Meet Mara →','primary'):btn('hunt:rats','Enter the canals →','primary',state.hp<=0)}</div></div><div class="section-row"><h3>Choose your trouble</h3><small>One tap. One exchange.</small></div><div class="hunt-list">${G.ENEMIES.filter(e=>e.id!=='boss').map(e=>{const locked=e.level>state.level+2;return `<button class="hunt-row ${locked?'locked-row':''}" data-action="hunt:${e.id}" ${locked||state.hp<=0?'disabled':''}>${enemyArt(e)}<div class="hunt-info"><div class="hunt-name">${e.name}</div><p>${e.location}${q?.target===e.id?' · Current contract':''}</p><div class="hunt-meta"><span>${e.hp} HP</span><span>${Math.floor((20+12*e.level)*(e.level-state.level<=-6?.25:e.level-state.level<=-3?.6:1))} XP</span><span>${e.coins} coins</span></div></div><span class="hunt-level">${locked?`UNLOCKS LV ${e.level-2}`:`LV ${e.level}`}</span>${icon(locked?'lock':'chevron','hunt-arrow')}</button>`;}).join('')}</div><p class="bottom-note">${icon('shield')} Progress comes from your actions. The canals can wait for you.</p>`;}
function combatView(){const f=state.fight,e=G.ENEMIES.find(x=>x.id===f.enemy),intent=G.intent(state),A=G.ABILITIES||{},main=G.mainActionKeys?G.mainActionKeys(state):G.primaryActions?G.primaryActions(state):{skill:'cast',combined:'combo'};const secondary=[...(state.equippedAbilities||[]).map(id=>[id==='arc'?'cast':id,A[id]?.name||id]),['recover','Recover'],...(e.id==='boss'&&f.hp<e.hp*.65&&!f.vented?[['vent','Vent']]:[]),['withdraw','Withdraw']];const primaryKeys=new Set(['attack',main.skill,main.combined,'guard']);const seen=new Set(),defs=[];for(const key of ['attack',main.skill,main.combined,'guard'])if(!seen.has(key)){seen.add(key);defs.push(key);}for(const key of ['recover','withdraw','vent'])if(defs.length<4&&!seen.has(key)){seen.add(key);defs.push(key);}const keyIcon={attack:'sword',cast:'bolt',combo:'spark',driving:'sword',guardstrike:'shield',guard:'shield',brace:'shield',disrupt:'sword',mend:'cross',aegis:'shield',expose:'spark',recover:'rest',vent:'settings',withdraw:'exit'};return `<section class="encounter bursar-stage"><div class="encounter-top"><div class="stage-readout"><div class="eyebrow">${e.location.toUpperCase()} · EXCHANGE ${f.round+1}</div><h2>${e.name}</h2><p>${e.blurb}</p><div class="encounter-badges"><span>LEVEL ${e.level}</span><span>ARMOR ${e.armor}</span><span>WARD ${e.ward}</span></div></div>${enemyArt(e)}</div><div class="enemy-health"><label><span>ENEMY HEALTH</span><span>${f.hp} / ${e.hp}</span></label><div class="bar" role="meter" aria-label="Enemy health" aria-valuemin="0" aria-valuemax="${e.hp}" aria-valuenow="${f.hp}"><i style="width:${f.hp/e.hp*100}%"></i></div></div><div class="intent ${intent.heavy?'heavy':''}">${icon(intent.heavy?'bolt':'shield')}<div><strong>${intent.name}</strong><small>${intent.heavy?'Heavy attack · Guard or Disrupt can help.':'The enemy responds after your action.'} ~${intent.damage} raw damage.</small></div>${f.charge?'<span class="hunt-level gold" style="margin-left:auto">RESERVOIR +10%</span>':''}</div></section><div class="combat-controls rune-console" aria-label="Combat actions" tabindex="-1"><div class="combat-timing action-recovery"><div class="recovery-heading">${icon('clock')}<span id="action-ready-text" role="status" aria-live="polite">Ready for your next action</span><span id="action-delay-count">Ready</span></div><span id="action-delay-track" class="action-delay-track" role="progressbar" aria-label="Action recovery" aria-valuemin="0" aria-valuemax="${G.ACTION_DELAY_MS}" aria-valuenow="${G.ACTION_DELAY_MS}"><i></i></span></div><div class="action-grid">${defs.map((k,index)=>{const a=G.actionInfo(state,k)||{label:k,cost:'',desc:''};return `<button class="action-btn ${index===2?'preferred':''}" data-action="combat:${k}" ${a.reason?'disabled':''} title="${esc(a.reason||a.desc)}" aria-label="${esc(a.label)}. ${esc(a.reason||a.desc)}">${icon(keyIcon[k]||'spark')}<span>${esc(a.label)}</span><small>${esc(a.cost)}</small></button>`;}).join('')}</div><div class="secondary-actions">${secondary.filter(([k])=>!primaryKeys.has(k)).map(([k,label])=>{const a=G.actionInfo(state,k)||{label:label,cost:'',desc:''};return btn('combat:'+k,`${icon(keyIcon[k]||'spark')}${esc(a.label||label)}${(f.cooldowns[k]||0)>f.round?` · ${f.cooldowns[k]-f.round}`:''}`,'',!!a.reason);}).join('')}</div><div class="combat-hint">One exchange per tap · 0.65-second action delay · No queued actions</div></div>${report()}`;}
function report(){return renderEncounterRecord(state);}
function outcome(){return renderEncounterOutcome(state)+pointNotice()+report();}
function delveView(){if(!state.delve)return `<div class="hero"><div class="hero-top"><span class="eyebrow">THE MUNICIPAL WORKS</span><span class="region-pill">SOLO DELVE · LV 6+</span></div><div class="eyebrow">A VOLUNTARY BAD IDEA</div><h2>Someone has to go below.</h2><p>Five checkpoints. One camp. A supervisor with authority issues. Take your prepared build into the flood-control works.</p><div class="hero-footer"><small>Completed room rewards stay yours.</small>${btn('delve-start',state.level<6?'Unlocks at level 6':!state.clears&&!G.contractStatus(state,'municipal_works').active&&!G.contractStatus(state,'municipal_works').completed?'Accept the major contract first':'Enter the works →','primary',state.level<6||state.hp<=0||(!state.clears&&!G.contractStatus(state,'municipal_works').active&&!G.contractStatus(state,'municipal_works').completed))}</div></div><section class="panel" style="margin-top:20px"><h3>Know what you’re signing.</h3><p class="muted">Equipment and attributes lock during the delve. You get one full recovery at camp. Every exchange still needs your input. Returning to town ends this run and resets the camp.</p><p class="muted">${btn('nav:story','Review story requirements →','text-button')}</p><p class="muted no-margin">The Superintendent unlocks a guaranteed first-clear item choice. The ordinary hunting grounds remain available.</p></section>`;
const d=state.delve;return `<section class="panel"><div class="eyebrow">THE MUNICIPAL WORKS · SOLO EXPEDITION</div><div class="delve-path">${['Gatehouse','Inspection','Chosen route','One camp','Pump chamber'].map((n,j)=>`<div class="delve-node ${j<d.node?'done':j===d.node?'current':''}">${j+1}. ${n}</div>`).join('')}</div>${d.node===0?`<h2>The gatehouse</h2><p class="muted">A Chainback Crab blocks the maintenance entrance. Its clamp winds up slowly. A spell goes through its armor rather nicely.</p>${btn('delve:enter','Clear the gatehouse →','primary')}`:d.node===1?`<h2>Two ways to help.</h2><p class="muted">Mara’s crew is somewhere below. Their records might say where. But the eastern overflow pump is failing, too.</p><div class="choices">${btn('delve:records','<strong>Recover the ledger</strong><small>Face the Siltbound Inspector. Find evidence of the missing crew.</small>','choice')}${btn('delve:overflow','<strong>Secure the pump</strong><small>Face a Floodgate Hound. Protect the homes above the eastern canal.</small>','choice')}</div><p class="tiny muted">Both routes reach the camp and boss. Your choice is recorded in the Chronicle.</p>`:d.node===3?`<h2>A moment above water.</h2><p class="muted">A dry maintenance platform. A kettle. Nothing trying to eat you. You have ${d.campUsed?'used your recovery charge':'one full recovery available'}.</p><div class="outcome-actions">${btn('delve:rest',d.campUsed?'Camp used':'Use camp recovery','subtle',d.campUsed)}${btn('delve:continue','Face the Superintendent →','primary')}</div>`:'<h2>The works are waiting.</h2>'}<p class="mechanics">${btn('delve-leave','Return to town · end this run','text-button')}</p></section>`;}
function huntView(){return shell(`<div class="layout"><div class="main-column">${!state.fight?`<div class="tabs">${btn('tab:hunts',`${icon('hunt')} Hunting grounds`,huntTab==='hunts'?'active':'')}${btn('tab:delve',`${icon('lock')} Municipal Works`,huntTab==='delve'?'active':'')}</div>`:''}${state.fight?combatView():state.last?outcome():`${pointNotice()}${huntTab==='delve'?delveView():hub()}`}</div>${rightSide()}</div>`,'Below the waterline','A small town. An ancient system. A growing list of problems.');}
const percent=v=>(v*100).toFixed(2)+'%';
const STAT_NAMES={heavyPower:'Heavy power',precisionPower:'Precision power',spellPower:'Spell power',physicalAcc:'Physical accuracy',spellAcc:'Spell accuracy',hp:'Max health',mp:'Max mana',sp:'Max stamina',evasion:'Evasion',critChance:'Critical chance',equipmentDropChance:'Equipment drops',mendHealing:'Mend healing'};
function attributeEffect(k){
 const p=G.attributePreview(state,k);
 return p.changes.map(c=>`${STAT_NAMES[c.field]} ${['critChance','equipmentDropChance'].includes(c.field)?percent(c.before):c.before} → ${['critChance','equipmentDropChance'].includes(c.field)?percent(c.after):c.after}`).join(' · ');
}
function buildInspector(){
 const t=G.totals(state),id=state.fight?.enemy||(G.ENEMIES.some(e=>e.id===state.settings.inspectTarget)?state.settings.inspectTarget:G.ENEMIES.filter(e=>e.level<=state.level).at(-1)?.id)||'rats',enemy=G.ENEMIES.find(e=>e.id===id),w=resolved(state.gear.weapon);
 const physicalMitigation=G.mitigation(t.armor,enemy.level),arcaneMitigation=G.mitigation(t.ward,enemy.level),enemySolidHit=G.hitChance(25+4*enemy.level,t.evasion);
 return `<section class="panel stats-inspector"><div class="panel-label">BUILD INSPECTOR · ACTUAL COMBAT RULES</div><h3>Know what your build does.</h3><p class="muted">Your ${w.name} uses <strong>${w.channel==='spell'?'Intellect':w.channel==='precision'?'Finesse':'Might'}</strong> for Attack. Compare a target before spending points or changing equipment.</p><label class="inspect-target" for="inspect-target">Compare against<select id="inspect-target" ${state.fight?'disabled':''}>${G.ENEMIES.map(e=>`<option value="${e.id}" ${e.id===id?'selected':''}>${e.name} · level ${e.level}</option>`).join('')}</select></label><div class="derived-grid">${[['Heavy power',t.heavyPower],['Precision power',t.precisionPower],['Spell power',t.spellPower],['Physical accuracy',t.physicalAcc],['Spell accuracy',t.spellAcc],['Evasion',t.evasion],['Critical chance',percent(t.critChance)],['Critical damage','125%'],['Mend healing',t.mendHealing],['Physical reduction',percent(physicalMitigation)],['Arcane reduction',percent(arcaneMitigation)],['Enemy glancing chance',percent(1-enemySolidHit)]].map(([n,v])=>`<div class="derived-stat"><span>${n}</span><strong>${v}</strong></div>`).join('')}</div><p class="inspector-context">${state.fight?'Current encounter: includes the enemy’s stance, stored charge, and any adaptation.':'Neutral stance: excludes encounter-only Guard, wards, Reservoir charges, and boss openings.'} Reduction and accuracy depend on the selected enemy. Critical chance applies to solid hits.</p><div class="damage-profiles">${[['attack','Attack','Free'],['cast','Arc Bolt','12 mana'],['combo','Wardcast','12 mana · 8 stamina + Guard']].map(([key,label,cost])=>{const a=G.actionProfile(state,key,id);return `<div class="damage-profile"><div class="flex-between"><h4>${label}</h4><span>${a.available?cost:'Requires '+(key==='combo'?'a focus & shield':'a focus')}</span></div><dl><div><dt>Normal / critical / glancing</dt><dd>${a.normal} / ${a.critical} / ${a.glance}</dd></div><div><dt>Solid-hit chance</dt><dd>${percent(a.hitChance)}</dd></div><div><dt>Average per action</dt><dd>${a.average.toFixed(1)} ${a.channel}</dd></div></dl>${!a.available?'<p class="muted">Preview only; this action is unavailable with your equipment.</p>':''}</div>`;}).join('')}</div></section><section class="panel fortune-panel"><div class="panel-label">LUCK · SMALL EDGES, REAL EFFECTS</div><h3>Fortune has rules.</h3><div class="derived-grid"><div class="derived-stat"><span>Total Luck</span><strong>${t.lck}</strong></div><div class="derived-stat"><span>Equipment-drop chance</span><strong>${percent(t.equipmentDropChance)}</strong></div></div><p>Luck above 8 improves critical chance and equipment drops with diminishing returns. A Copper-Thread Charm adds +4 Luck and is available from the Curio dealer for 25 coins.</p><p class="muted">Guaranteed XP, coins, materials, and first-boss rewards stay guaranteed. Luck never grants extra exchanges or bypasses the action delay. Duplicate equipment drops become salvaged fittings.</p>${btn('shop-luck','Visit the outfitter →','text-button')}</section>`;
}
function tabButton(id,label){return btn('char-tab:'+id,`${icon(id)}${label}`,charTab===id?'active':'');}
function requirementsView(req,raw={}){if(!req)return '';const rows=[];if(req.level?.required>0)rows.push(`Level ${state.level} / ${req.level.required}`);if(raw.questOrGuards){const needQ=req.quest?.required||raw.quest||0,needG=req.usefulGuards?.required||raw.usefulGuards||0,met=!!(req.quest?.met||req.usefulGuards?.met);if(needQ||needG)rows.push(`${met?'Met · ':''}${needQ} contracts or ${needG} useful Guards`);}else if(req.quest?.required>0)rows.push(`Contracts ${state.quest} / ${req.quest.required}`);if(req.guardCount?.required>0)rows.push(`Useful Guards ${state.guardCount||0} / ${req.guardCount.required}`);if(req.usefulGuards?.required>0&&!raw.questOrGuards)rows.push(`Useful Guards ${state.usefulGuards||0} / ${req.usefulGuards.required}`);return rows.length?`<div class="requirement-list"><strong>Requirements</strong>${rows.map(x=>`<span>${esc(x)}</span>`).join('')}</div>`:'';}
function abilityScreen(){
 const A=G.ABILITIES||{},ids=Object.keys(A),active=ids.filter(id=>A[id].kind==='active'),passives=ids.filter(id=>A[id].kind==='passive'),used=G.attunementUsed?G.attunementUsed(state):0,locked=!!state.fight||!!state.delve;
 const card=id=>{const a=A[id],st=G.abilityStatus(state,id)||{},mastery=st.mastery||state.mastery?.[id]||a.mastery||{},passiveOverflow=a.kind==='passive'&&used-(A[state.passive]?.kind==='passive'?A[state.passive].attunement:0)+(a.attunement||0)>6,activeOverflow=a.kind==='active'&&!st.equipped&&used+(a.attunement||0)>6,slotOverflow=a.kind==='active'&&!st.equipped&&(state.equippedAbilities||[]).length>=3,equipBlock=passiveOverflow?'Exceeds the 6-point attunement limit.':activeOverflow?'Exceeds the 6-point attunement limit.':slotOverflow?'All three active slots are occupied.':'';return `<article class="ability-card ${st.equipped?'equipped':''} ${!st.learned?'ability-locked':''}"><div class="ability-card-head"><div><span class="eyebrow">${a.kind==='passive'?'PASSIVE':'ACTIVE'} · ${a.attunement||0} ATTUNEMENT</span><h3>${esc(a.name)}</h3></div><span class="ability-state">${st.equipped?'Equipped':st.learned?'Learned':'Locked'}</span></div><p>${esc(a.desc||'')}</p>${a.focus?'<p class="ability-focus">Requires a focus-capable weapon or offhand to use Arc Bolt.</p>':''}${requirementsView(st.requirements,a.requires)}${!st.eligible&&st.reason?`<p class="ability-reason">${esc(st.reason)}</p>`:''}${st.learned&&!st.equipped&&equipBlock?`<p class="ability-reason">${esc(equipBlock)}</p>`:''}${a.kind==='active'?`<div class="ability-meta">Cost: ${a.mp||0} mana · ${a.sp||0} stamina <span>Mastery rank ${mastery.rank||1} · ${mastery.marks||0} marks</span></div>`:''}${st.learned?(a.kind==='active'?btn(st.equipped?'ability-remove:'+id:'ability-equip:'+id,st.equipped?'Remove from active bar':'Equip ability','subtle',locked||(!st.equipped&&(!st.learned&&!st.eligible||!!activeOverflow||!!slotOverflow))):`<div class="ability-meta">Passive slot ${state.passive===id?'· Equipped':'· Select one'}</div>${btn(state.passive===id?'ability-remove:'+id:'ability-equip:'+id,state.passive===id?'Unequip passive':passiveOverflow?'Exceeds attunement':'Equip passive','subtle',locked||passiveOverflow&&state.passive!==id)}`):btn('ability-learn:'+id,st.eligible?'Learn ability':'Requirements not met','',locked||!st.eligible)}</article>`;};
 const masteryChoices=active.map(id=>{const st=G.abilityStatus(state,id)||{},m=st.mastery||{};if((m.rank||0)<3)return '';const choices=m.choices||[];return `<section class="mastery-card"><div class="flex-between"><div><span class="eyebrow">RANK 3 MASTERY</span><h3>${esc(A[id].name)}</h3></div><span class="hunt-level">${(m.rank3Choice||m.choice)?'CHOICE SET':'CHOOSE ONE'}</span></div><p>Choose the behavior that fits your build. The engine will apply the selected rank 3 effect.</p>${choices.map(c=>{const key=typeof c==='string'?c:c.id||c.key,label=typeof c==='string'?({economy:'Economy',power:'Power',barrier:'Larger barrier',recovery:'Faster recovery',immunity:'Shorter immunity',healing:'Greater healing'})[c]||c:c.name||c.label||key,desc=(m.descriptions||{})[key]||(typeof c==='string'?'':c.desc||c.description||'');return `<button data-action="mastery:${id}:${esc(key)}" class="mastery-choice ${(m.rank3Choice||m.choice)===key?'selected':''}" ${locked?'disabled':''}><strong>${esc(label)}</strong><small>${esc(desc)}</small></button>`;}).join('')}</section>`;}).join('');
 return `<div class="ability-overview"><div class="capacity-card"><strong>Attunement ${used} / 6</strong><span>${(state.equippedAbilities||[]).length} / 3 active slots · 1 passive slot</span></div><p class="muted">Learn abilities as you meet their listed requirements. Equip up to three active abilities; only equipped actions appear during combat. Rank progress comes from eligible victories.</p>${locked?'<div class="point-notice">Abilities are locked during an encounter or expedition.</div>':''}</div><section><div class="section-row"><h2>Active abilities</h2><small>Only equipped actions enter combat</small></div><div class="ability-grid">${active.map(card).join('')}</div></section><section><div class="section-row"><h2>Passive abilities</h2><small>One equipped</small></div><div class="ability-grid">${passives.map(card).join('')}</div></section>${masteryChoices?`<section><div class="section-row"><h2>Mastery choices</h2></div><div class="mastery-grid">${masteryChoices}</div></section>`:''}${Object.entries(state.mastery||{}).length?`<section class="panel mastery-progress"><div class="panel-label">MASTERY PROGRESS</div>${Object.entries(state.mastery).map(([id,m])=>`<div class="loadout-item"><div><b>${esc(A[id]?.name||id)}</b><small>${m.rank>=3?'Rank 3 · Prototype cap':`${m.marks} / ${3+2*m.rank} qualifying victories to rank ${m.rank+1}`}</small></div><span class="hunt-level">RANK ${m.rank}</span></div>`).join('')}</section>`:''}`;
}
function characterManager(){const locked=!C.rosterCanChange(roster,state);modal('Your adventurers',`<p>${roster.characters.length} of ${C.MAX_CHARACTERS} character slots used. Create or switch characters without removing any existing adventure.</p><div class="character-list">${roster.characters.map(entry=>{const s=entry.state,active=entry.id===roster.activeId;return `<div class="character-list-row"><div><strong>${esc(s.name)}</strong><small>${esc(s.race)} · Level ${s.level} · ${esc(s.origin)}</small></div>${active?'<span class="active-character-tag">Active</span>':btn('switch-character:'+entry.id,'Switch','subtle',locked)}</div>`;}).join('')}</div>${roster.characters.length>=C.MAX_CHARACTERS?'<p class="ability-reason">All six character slots are in use. Export a save before clearing anything; character deletion is not available here.</p>':''}<div class="modal-actions">${btn('new-character-form','Create character','primary',locked||roster.characters.length>=C.MAX_CHARACTERS)}${btn('close','Done','subtle')}</div>`, 'CHARACTER ROSTER');}
function newCharacterModal(){modal('Create another adventurer',`<p>Your current character will be saved in the roster. This creates an additional local character.</p><label>Adventurer name<input id="new-name" maxlength="32" placeholder="Your name" autocomplete="given-name"></label><label>Race<select id="new-race"><option>Human</option><option>Stonekin</option></select></label><label>Background<textarea id="new-origin" maxlength="70" rows="2" placeholder="Former canal surveyor">Former canal surveyor</textarea></label><label>Starter kit<select id="new-kit"><option value="bulwark">Bulwark · Inspector’s Rod, shield, Arc Bolt</option><option value="caster">Caster · Inspector’s Rod, focus, Arc Bolt</option><option value="duelist">Duelist · Surveyor’s Blade, charm, Driving Strike</option><option value="breaker">Breaker · Canal-Iron Sword, shield, Driving Strike</option></select></label><p class="wizard-note">Starter kit is not a class. Every character begins with 20 coins.</p><div class="modal-actions">${btn('create-character','Create character','primary')}${btn('close','Cancel','subtle')}</div>`,'NEW LOCAL CHARACTER');}
function earnedAttributeBudget(s){const p=G.progression(s);return 68+4*(s.level-1)+(p?.part||s.part||1)-1;}
function levelProgressPanel(){const p=G.progression(state);if(!p)return '';const capped=!!p.capped,levelPercent=capped?100:Math.max(0,Math.min(100,p.levelXP/p.levelRequired*100)),partPercent=capped?100:Math.max(0,Math.min(100,p.partXP/p.partRequired*100));return `<section class="panel progression-panel"><div class="progression-head"><div><div class="eyebrow">CHARACTER PROGRESSION</div><strong>Level ${p.level} · Part ${p.part} of ${p.parts}</strong></div><span>${p.totalEarned} attribute points earned</span></div><div class="xp-track"><label><span>FULL LEVEL PROGRESS</span><span>${capped?'PROTOTYPE CAP':`${p.levelXP} / ${p.levelRequired} XP`}</span></label><div class="bar" role="meter" aria-label="Level experience" aria-valuemin="0" aria-valuemax="${p.levelRequired||1}" aria-valuenow="${p.levelXP}"><i style="width:${levelPercent}%"></i></div></div><div class="part-track-label"><span>ATTRIBUTE MILESTONE ${capped?'COMPLETE':`· PART ${p.part} / ${p.parts}`}</span><span>${capped?'No further points at the prototype cap':`${p.partXP} / ${p.partRequired} XP · Next: +1 attribute point`}</span></div><div class="part-track" aria-label="Part ${p.part} of ${p.parts}; ${p.partXP} of ${p.partRequired} experience to the next attribute point">${Array.from({length:p.parts},(_,i)=>`<span class="${i+1<p.part?'complete':i+1===p.part&&!capped?'current':''}" ${i+1===p.part&&!capped?`aria-current="step"`:''}>${i+1===p.part&&!capped?`<i style="width:${partPercent}%"></i>`:''}</span>`).join('')}</div></section>`;}
function characterView(){const t=G.totals(state),locked=!!state.fight||!!state.delve,selected=state.gear.weapon;const tabs=`<div class="tabs sheet-tabs" role="tablist" aria-label="Character sheet">${tabButton('overview','Overview')}${tabButton('attributes',`Attributes${state.points?` · ${state.points}`:''}`)}${tabButton('abilities','Abilities')}${tabButton('gear','Gear')}</div>`;
 const overview=renderCharacterOverview(state,{levelProgressHTML:levelProgressPanel(),inspectorHTML:buildInspector()});
 const attributes=`<section class="panel"><div class="panel-label"><span>YOUR ATTRIBUTES</span><span class="gold">${state.points} POINTS AVAILABLE</span></div>${locked?'<p class="tiny muted">Attribute changes are locked during an encounter or expedition.</p>':'<p class="tiny muted">Seven attributes. Every point has an inspectable effect. Luck starts at 8; use a free respec to try a different investment.</p>'}<div class="attributes">${Object.entries(G.ATTRS).map(([k,[name,description]])=>`<div class="attribute"><span class="attr-code">${k.toUpperCase()}</span><div><b>${name}</b><span class="attribute-description">${description}</span><small>${attributeEffect(k)}</small><span class="attribute-source">Invested ${state.stats[k]} + gear ${t.gearBonuses[k]} = ${t[k]}</span></div><span class="attr-value">${t[k]}</span><button data-action="stat:${k}" aria-label="Add one point to ${name}" ${locked||state.points<=0?'disabled':''}>+</button></div>`).join('')}</div><div class="flex-between" style="margin-top:12px"><span class="tiny muted">Budget ${earnedAttributeBudget(state)} · Invested ${Object.values(state.stats).reduce((a,b)=>a+b,0)} · Unspent ${state.points}</span>${btn('respec','Reallocate points →','text-button tiny',locked)}</div></section><section class="panel"><div class="panel-label">PRACTICE LOADOUTS · NOT CLASSES</div><p class="tiny muted">Try an arrangement. Every attribute, item and ability stays open to you.</p><div class="kit-grid">${[['bulwark','Rod & shield','Intellect · durable casting',selected==='rod'&&state.gear.offhand==='shield'],['caster','Rod & focus','Intellect · spell output',selected==='rod'&&state.gear.offhand==='focus'],['duelist','Blade & charm','Finesse · accuracy',selected==='blade'],['breaker','Sword & shield','Might · physical pressure',selected==='sword']].map(([id,n,d,sel])=>btn('kit:'+id,`${n}<small>${d}</small>`,`kit ${sel?'selected':''}`,locked)).join('')}</div></section>`;
 return shell(`<div class="main-column character-sheet">${tabs}${charTab==='attributes'?attributes:charTab==='abilities'?abilityScreen():charTab==='gear'?equipmentPanel():overview}</div>`,'A build of your own','Resources, attributes, equipment, and abilities in one readable record.','CHARACTER RECORD · BRACKEN QUAY');}
function itemStats(i){return [i.base?`${i.base} base`:null,i.armor?`${i.armor} armor`:null,i.ward?`${i.ward} ward`:null,i.spellBase?`${i.spellBase} spell base`:null,...Object.entries(i.stats||{}).map(([k,v])=>`${v} ${G.ATTRS[k]?.[0]||k}`),i.upgrade?`+${i.upgrade} upgrade`:null,i.prefix?G.PREFIXES?.[i.prefix]?.name:null,i.suffix?G.SUFFIXES?.[i.suffix]?.name:null,i.id==='seal'?'15 barrier on useful Guard':null].filter(Boolean);}
function compare(id,targetSlot=null){const i=resolved(id),choices=G.slotChoices(state,id),selected=targetSlot||choices[0]||null,owned=state.bag.includes(id),eq=selected?state.gear[selected]===id:Object.values(state.gear).includes(id),oldId=selected?state.gear[selected]:state.gear[i.slot],old=oldId?resolved(oldId):null;const slotCards=!targetSlot&&choices.length>1?`<div class="target-slot-choices"><strong>Choose a slot</strong>${choices.map(slot=>{const current=state.gear[slot]?resolved(state.gear[slot]):null;return `<button data-action="equip:${id}:${slot}" class="slot-choice" ${state.fight||state.delve?'disabled':''}><span>${SLOT_LABELS[slot]||G.SLOTS?.[slot]||slot}</span><small>Replaces ${current?.name||'Empty'}</small></button>`;}).join('')}</div>`:'';modal(i.name,`<p>${esc(i.desc)}</p><div class="compare"><div><span class="eyebrow">CURRENTLY EQUIPPED · ${esc(SLOT_LABELS[selected]||G.SLOTS?.[selected]||selected||i.slot)}</span>${old?itemArt(old,'large'):''}<h3>${esc(old?.name||'Empty slot')}</h3><p>${old?itemStats(old).map(esc).join('<br>'):'No item in this slot.'}</p></div><div><span class="eyebrow">THIS ITEM · LEVEL ${i.level}</span>${itemArt(i,'medium')}<h3>${esc(i.name)}</h3><p>${itemStats(i).map(esc).join('<br>')||'An authored equipment trait.'}</p></div></div>${equipmentEffectPreview(id,selected)}${i.slot==='weapon'&&i.channel!=='spell'?`<p class="modal-help">Physical weapon skills do not need a focus. Driving Strike can be learned at level 1 and equipped from Character → Abilities.</p>${btn('nav-abilities','Review physical skills →','text-button')}`:''}<p class="modal-help">${i.channel?`Strike uses ${i.channel==='heavy'?'Might':i.channel==='precision'?'Finesse':'Intellect'} with this weapon. `:''}${i.focus?'This item enables focus-dependent spells. ':''}Equipment changes are available outside encounters and expeditions.</p><div class="modal-actions">${eq?btn('close','Keep equipped','primary'):!selected?'<p class="ability-reason">No compatible slot is available right now.</p>':btn('equip:'+id+':'+selected,'Equip in '+(SLOT_LABELS[selected]||selected),'primary',!owned||!!state.fight||!!state.delve||state.level<i.level)}${btn('close','Back','subtle')}</div>${slotCards}`,'EQUIPMENT COMPARISON');}
function slotChooser(slot){const currentId=state.gear?.[slot],current=currentId?resolved(currentId):null,locked=!!state.fight||!!state.delve;const choices=state.bag.map(id=>resolved(id)).filter(i=>i&&G.slotChoices(state,i.id).includes(slot));const occupied=slot==='offhand'&&resolved(state.gear.weapon)?.twoHanded;modal(`${SLOT_LABELS[slot]||G.SLOTS?.[slot]||slot} slot`,`${current?`<p>Equipped: <strong>${esc(current.name)}</strong>. Review another compatible item to compare before equipping.</p>`:'<p>This slot is empty. Choose gear you own to inspect its comparison before equipping.</p>'}${occupied?`<p class="ability-reason">Occupied by your two-handed ${esc(resolved(state.gear.weapon).name)}.</p>`:''}${choices.length?`<div class="slot-choice-list">${choices.map(i=>{const inSlot=currentId===i.id;return `<button data-action="slot-select:${i.id}:${slot}" class="slot-choice" ${locked||inSlot?'disabled':''}><span>${esc(i.name)}${inSlot?' · Equipped here':''}</span><small>${itemStats(i).map(esc).join(' · ')||esc(i.desc)}</small></button>`;}).join('')}</div>`:occupied?'<div class="empty-state">Your two-handed weapon occupies this slot.</div>':`<div class="empty-state">No compatible owned gear. Find equipment in the Curio dealer or earn it on a hunt.${btn('open-shop','Visit the outfitter','text-button')}</div>`}<div class="modal-actions">${currentId?btn('compare:'+currentId,'Review current item','subtle'):''}${btn('close','Close','text-button')}</div>`, 'EQUIPMENT SLOT');}

function costLine(cost){const mats=Object.entries(cost?.materials||{}).map(([name,n])=>`${n} ${name}`).join(' + ');return [cost?.coins?`${cost.coins} coins`:null,mats||null].filter(Boolean).join(' + ')||'No cost';}
function exchangeOutput(recipe){return [...Object.entries(recipe.gain||{}).map(([name,n])=>`${n} ${name}`),...(recipe.gainItems||[]).map(id=>`1 ${resolved(id)?.name||id}`)].join(' + ')||'No listed reward';}
function costSources(cost){const mats=Object.keys(cost?.materials||{});return mats.length?mats.map(m=>`${m}: ${MATERIAL_SOURCES[m]||'Collect during hunts or use another exchange'}`).join('; '):'';}
function exchangeBlock(recipe){if(recipe.level&&state.level<recipe.level)return `Requires level ${recipe.level}.`;const owned=(recipe.gainItems||[]).find(id=>state.bag?.includes(id));return owned?`Already owned: ${resolved(owned)?.name||owned}.`:'';}
function exchangeCanAfford(recipe){return Object.entries(recipe.cost||{}).every(([m,n])=>(state.materials?.[m]||0)>=n)&&(state.coins||0)>=(recipe.coins||0);}
const MATERIAL_SOURCES={'Ledger scraps':'Rats and scavengers','Canal iron':'Scavengers and the Lockwarden','Repair fittings':'Contracts and salvage exchanges','Salvaged fittings':'Duplicate gear and workbench exchanges','Runic residue':'Wisps and the Inspector','Chainback shell':'The chainback crab','Stamped brass':'Siltbound Inspector hunts','Floodglass':'Late hunts and material exchanges','Floodglass Fragment':'The Superintendent, every clear'};
function workbenchView(){const locked=!!state.fight||!!state.delve;const items=state.bag.map(id=>resolved(id)).filter(Boolean);const exchanges=Object.values(G.EXCHANGES||{});return `<section class="workbench-intro panel"><div class="panel-label">${renderServiceArt('toolkit',{size:'small'})} MUNICIPAL WORKBENCH</div><h2>Make what you have go further.</h2><p>Every exchange, upgrade, and reforge shows its full cost and resulting item before anything is spent. Equipment work is unavailable during hunts and delves.</p><div class="coin-chip">${icon('coin')} ${state.coins} coins available</div>${locked?'<p class="locked-note">The workbench is closed until you return to town.</p>':''}</section><details class="workbench-section bench-group"><summary>${icon('materials')}Material exchanges<small>Convert materials or assemble gear</small></summary><div class="exchange-grid">${exchanges.map(recipe=>{const blocked=exchangeBlock(recipe);return `<article class="exchange-card"><div class="eyebrow">MATERIAL EXCHANGE</div><h3>${esc(recipe.name)}</h3><div class="exchange-flow"><div><small>USES</small><strong>${Object.entries(recipe.cost||{}).map(([m,n])=>`${n} ${esc(m)}`).join(' + ')}</strong></div><span>→</span><div><small>MAKES</small><strong>${esc(exchangeOutput(recipe))}</strong></div></div><p class="material-hint">Source: ${Object.keys(recipe.cost||{}).map(m=>esc(MATERIAL_SOURCES[m]||'Hunts and contracts')).join('; ')}</p><p class="explicit-cost">Cost: ${costLine({coins:recipe.coins,materials:recipe.cost})}</p>${blocked?`<p class="ability-reason">${esc(blocked)}</p>`:''}${btn('exchange:'+recipe.id,blocked?'Unavailable · See reason':'Review exchange','subtle',locked||!!blocked)}</article>`;}).join('')}</div></details><details class="workbench-section bench-group"><summary>${icon('upgrade')}Upgrade or reforge gear<small>Inspect changes before spending</small></summary>${items.length?`<div class="workbench-items">${items.map(i=>{const up=G.upgradePreview(state,i.id);return `<article class="workbench-item"><div><span class="eyebrow">${SLOT_LABELS[i.slot]||G.SLOTS?.[i.slot]||i.slot} ${i.upgrade?`· +${i.upgrade}`:''}</span>${itemArt(i,'medium')}<h3>${esc(i.name)}</h3><p>${itemStats(i).map(esc).join(' · ')||esc(i.desc)}</p></div><div class="workbench-actions">${costSources(up.cost)?`<small class="material-hint">Upgrade material: ${esc(costSources(up.cost))}</small>`:''}${btn('upgrade:'+i.id,up.level>=3?'Preview upgrade · cap reached':`Preview upgrade · ${costLine(up.cost)}`,'subtle',locked)}${['prefix','suffix'].map(kind=>{const options=Object.values(kind==='prefix'?G.PREFIXES||{}:G.SUFFIXES||{}).filter(x=>x.slots?.includes(i.slot));return options.length?btn(`affix-menu:${i.id}:${kind}`,`Reforge ${kind}`,'text-button tiny',locked):'';}).join('')}</div></article>`;}).join('')}</div>`:'<div class="empty-state">Bring equipment back from a hunt to begin upgrading and reforging it.</div>'}</details>`;}
function buyReview(id){const p=G.buyPreview(state,id),i=G.ITEMS[id];if(!i)return;modal(`Buy ${esc(i.name)}`,`<p>${esc(i.desc)}</p><div class="compare"><div><span class="eyebrow">ITEM</span>${itemArt(i,'medium')}<h3>${esc(i.name)}</h3><p>${itemStats(i).map(esc).join('<br>')||'No listed bonuses.'}</p></div><div><span class="eyebrow">FULL PRICE</span><h3>${p.price} coins</h3><p>Coins on hand: ${state.coins}</p></div></div>${p.reason?`<p class="ability-reason">${esc(p.reason)}</p>`:''}<p class="modal-help">Buying adds this item to your satchel. It does not equip it.</p><div class="modal-actions">${btn('buy-confirm:'+id,'Confirm purchase · '+p.price+' coins','primary',!p.allowed||!!state.fight||!!state.delve)}${btn('close','Cancel','subtle')}</div>`,(M.VENDORS[M.classifyVendor(id)]?.name||'Quay market').toUpperCase()+' · PURCHASE REVIEW');}
function sellReview(id){const p=G.sellPreview(state,id),i=resolved(id);modal(`Sell ${esc(i.name)}`,`<p>This sale is for unequipped gear only. Its affixes and upgrades are removed with the item; no materials are returned.</p><div class="compare"><div><span class="eyebrow">ITEM TO SELL</span>${itemArt(i,'medium')}<h3>${esc(i.name)}</h3><p>${itemStats(i).map(esc).join('<br>')||'No listed bonuses.'}</p></div><div><span class="eyebrow">COIN VALUE</span><h3>+${p.price} coins</h3><p>Coins on hand: ${state.coins} → ${state.coins+p.price}</p></div></div>${p.reason?`<p class="ability-reason">${esc(p.reason)}</p>${Object.values(state.gear).includes(id)?btn('open-gear','Go to Gear page to unequip','text-button'):''}`:''}<p class="modal-help">Nothing is removed and no coins are added until you confirm the sale.</p><div class="modal-actions">${btn('sell-confirm:'+id,'Confirm sale · +'+p.price+' coins','primary',!p.allowed||!!state.fight||!!state.delve)}${btn('close','Keep item','subtle')}</div>`,(M.VENDORS[M.classifyVendor(id)]?.name||'Quay market').toUpperCase()+' · SALE REVIEW');}
function bagView(){
 const locked=!!state.fight||!!state.delve,ids=state.bag.filter(id=>!Object.values(state.gear).includes(id));
 const tabs=`<div class="tabs bag-tabs" aria-label="Satchel sections">${btn('bag-tab:gear',`${icon('gear')}Spare gear`,bagTab==='gear'?'active':'')}${btn('bag-tab:materials',`${icon('materials')}Materials`,bagTab==='materials'?'active':'')}${btn('bag-tab:workbench',`${icon('workbench')}Workbench`,bagTab==='workbench'?'active':'')}</div>`;
 const materials=`<section class="panel"><h3>${renderServiceArt('materials',{size:'small'})} Materials on hand</h3>${Object.keys(state.materials||{}).length?Object.entries(state.materials).map(([n,c])=>`<div class="material-row"><span>${esc(n)}<small class="material-hint">${esc(MATERIAL_SOURCES[n]||'Collected during hunts and contracts')}</small></span><strong>${c}</strong></div>`).join(''):'<p class="muted">Complete a hunt to collect your first material.</p>'}<p class="mechanics">The workbench shows material sources and spends nothing until you confirm.</p>${btn('bag-tab:workbench',`${icon('workbench')}Open workbench`,'subtle')}</section>`;
 const inventory=`<div class="inventory-summary"><span>${ids.length} unequipped items</span>${btn('open-gear','Equipped slots','text-button')}</div>${locked?'<p class="ability-reason">Equipment changes are locked until the encounter or expedition ends.</p>':''}${ids.length?`<div class="item-grid">${ids.map(id=>{const i=resolved(id);return `<section class="item-card"><div class="item-card-top"><span class="item-symbol">${itemArt(i,'medium')}</span><div><h3>${esc(i.name)}</h3><small>${SLOT_LABELS[i.slot]||G.SLOTS[i.slot]} · Level ${i.level}</small></div></div><div class="item-stats">${itemStats(i).map(t=>`<span>${esc(t)}</span>`).join('')}</div><details class="item-lore"><summary>Details</summary><p>${esc(i.desc)}</p></details>${btn('compare:'+id,'Compare & equip','subtle')}</section>`;}).join('')}</div>`:`<section class="panel"><h3>Everything is in use.</h3><p>Your equipped gear is on the Character → Gear page. Find spare equipment through hunts, material exchanges, or the market.</p>${btn('nav:market',`${icon('market')}Visit Quay market`,'subtle')}</section>`}`;
 return shell(`<div class="satchel-page">${tabs}${bagTab==='materials'?materials:bagTab==='workbench'?workbenchView():inventory}</div>`,'Personal effects','Spare equipment, collected materials, and workbench services.','SATCHEL · BRACKEN QUAY');
}
function marketView(){return shell(M.renderMarket(state,{vendorId,mode:shopMode}),'Quay market','Three specialists. Compare your options before spending.','TRADERS · BRACKEN QUAY');}
function recordsTabs(){return `<div class="tabs records-tabs" aria-label="Records and help">${btn('nav:journal',`${icon('journal')}Chronicle`,view==='journal'?'active':'')}${btn('nav:world',`${icon('pin')}World`,view==='world'?'active':'')}${btn('nav:guide',`${icon('guide')}Field guide`,view==='guide'?'active':'')}</div>`;}
function worldView(){return shell(`${recordsTabs()}${renderWorldHub(state,{tab:worldTab})}`,'Beyond the Quay','Your local adventure, with room for a shared world.','WORLD RECORD · FUTURE CHAPTERS');}
function marketCompare(id,slot=null){const comparison=M.renderStockComparison(state,id,slot);if(comparison)modal(esc(comparison.title),comparison.body,'EQUIPMENT COMPARISON');}
function journalView(){return shell(`${recordsTabs()}<div class="layout"><div class="main-column">${state.pending!==null?`<div class="point-notice">A contract outcome is ready. ${btn('claim','Review →')}</div>`:''}<div style="padding:6px 0 0 5px">${state.journal.map(j=>`<article class="journal-entry ${j.kind}"><div class="eyebrow">${{story:'A NOTE IN YOUR STORY',growth:'VISIBLE PROGRESS',achievement:'ACHIEVEMENT EARNED',discovery:'A BUILD INTERACTION'}[j.kind]||'YOUR RECORD'}</div><h3>${esc(j.title)}</h3><p>${esc(j.text)}</p></article>`).join('')}</div></div><aside class="side-column">${titlePanel(`YOUR ACHIEVEMENTS ${icon('crown')}`,state.achievements.length?state.achievements.map(a=>`<div class="achievement-card"><h4>${esc(a.title)}</h4><p>${esc(a.text)}</p></div>`).join(''):'<h3>Notable, eventually.</h3><p>Rescue someone. Stand through a heavy attack. Interrupt a bad idea. The system keeps receipts.</p>')}${questPanel()}</aside></div>`,'A record worth keeping','Your choices, discoveries, and minor administrative triumphs.','THE CHRONICLE · YOUR ADVENTURE');}
const RULES=`<section class="guide-section"><h3>A slower story with smaller gains</h3><p>Minor contracts and major story milestones are accepted explicitly. Only qualifying victories after acceptance count toward their encounter objectives. Speak with Mara, report completed work, and take explicit story actions to move the chapter forward. Ordinary hunts always retain their own rewards.</p><p>Levels are split into four parts. Each completed part grants one attribute point. Full levels use three times the earlier prototype XP, with no timed waits or offline gains. The next part and next full level are both shown on your character sheet.</p></section><section class="guide-section"><h3>One tap. One exchange.</h3><p>The four-action row adapts to your weapon and equipped abilities. With Arc Bolt it offers Attack, Arc Bolt, Wardcast, and Defend; with Driving Strike it offers Attack, Driving Strike, Guardstrike, and Defend. Your action resolves first. If the enemy survives, it responds with the displayed intent. A shared 0.65-second delay follows every accepted combat action, including the final action of a fight. Switching buttons does not bypass it. Extra taps are ignored and never queued. The timer only re-enables controls: it never attacks, restores resources, or advances the game. The game never advances combat on a timer, while closed, or without an action.</p><p>Repeating a comfortable action is fine. Tougher encounters reward reading the intent. Rest at the Quay is an immediate, explicit action outside combat. Each completed exchange restores 3 mana and 4 stamina.</p></section><section class="guide-section"><h3>Your compact action bar</h3><ul><li><strong>Attack:</strong> free weapon strike, physical damage. Sword scales with Might; blade with Finesse; rod with Intellect.</li><li><strong>Arc Bolt:</strong> 1.25× spell damage. Costs 12 mana and needs a focus-tagged item.</li><li><strong>Wardcast:</strong> 0.85× spell damage and Guard together. Costs 12 mana and 8 stamina; requires a focus and shield. This is one budgeted action.</li><li><strong>Driving Strike:</strong> 1.15× physical weapon-channel damage for 8 stamina. It does not require a focus.</li><li><strong>Guardstrike:</strong> 0.80× physical weapon-channel damage plus Guard for 10 stamina. Requires a shield; no focus or mana.</li><li><strong>Defend:</strong> free Guard; reduces incoming damage by 35% this exchange.</li><li><strong>Recover:</strong> restore 15 mana and 20 stamina before the enemy responds.</li><li><strong>Learned active abilities:</strong> Arc Bolt costs 12 mana and begins learned. Brace costs 10 stamina; Mend 18 mana; Disrupt 14 stamina. Driving Strike, Aegis, and Expose each have their own listed costs. Their unlock requirements appear on the Abilities tab.</li><li><strong>Brace:</strong> Guard plus a barrier for this exchange. Blocks use for the next 2 exchanges. Its barrier grows with mastery.</li><li><strong>Disrupt:</strong> weapon strike. An accurate hit cancels a heavy wind-up; target then has 3 exchanges of interrupt immunity. Blocks use for the next 3 exchanges.</li><li><strong>Mend:</strong> restore health up to your maximum. Blocks use for the next 2 exchanges.</li><li><strong>Withdraw:</strong take half the enemy response, leave, and forfeit this fight’s rewards. Completed room rewards stay yours.</li></ul></section><section class="guide-section"><h3>Make a durable caster</h3><p>A new adventurer begins with Arc Bolt equipped and Prepared equipped as their passive. Reservoir unlocks at level 2 after one contract or two useful Guards; Sure Footing unlocks at level 2 after one contract. A useful Guard that prevents at least 20 hostile damage charges Reservoir. Your next Arc Bolt or Wardcast gains 10% raw spell damage. One charge maximum; it expires after the next exchange.</p><p>Try Defend or Wardcast against the rats’ Paperwork rush, then cast. The Chronicle records the first successful interaction. Unlocks are shown on the Abilities tab; learned abilities must also be equipped before their action appears in combat.</p></section><section class="guide-section"><h3>Seven attributes, one build</h3><ul>${Object.entries(G.ATTRS).map(([k,[n,d]])=>`<li><strong>${n} (${k.toUpperCase()}):</strong> ${d}.</li>`).join('')}</ul><p>Each attribute starts at a minimum of 8. The level-1 budget begins at 68: 56 baseline points plus 12 invested in your starter build. Each of four parts in a level awards one attribute point. The character sheet shows current-part and full-level progress; every milestone can be allocated when convenient. A free respec returns the 12 discretionary starter points plus your level-up points. Gear bonuses are separate.</p><p>Old saves receive base Luck 8 without losing existing stats, unspent points, gear, or progress. Luck grants no extra turn, XP, or passive income.</p></section><section class="guide-section"><h3>The numbers behind the fiction</h3><p>Max HP = <code>200 + 12×level + 10×VIT + 4×WIL</code><br>Mana = <code>60 + 3×WIL + 2×INT</code><br>Stamina = <code>60 + 2×VIT + 2×FIN</code></p><p>Raw strike = <code>item base + 0.9×power + 4</code>. Power = twice the scaling attribute + level. Arc Bolt uses spell power and its mastery rank. The focus offhand adds its spell base once, to spells.</p><p>Mitigation = <code>defense / (defense + 100 + 8×attacker level)</code>, capped at 65%. Armor protects from physical damage; ward from arcane. Critical hits deal 1.25× damage. Let <code>F = max(0, LCK−8) / (max(0, LCK−8)+40)</code>. Critical chance = <code>5% + 15%×FIN/(FIN+208) + 10%×F</code>, capped at 25%. Equipment-drop chance = <code>20% + 15%×F</code>. Critical chance is checked only on a solid hit. Insight no longer reduces critical chance. Accuracy is bounded at 65–98%; failed accuracy checks are glancing hits for 55% damage, to avoid empty clicks.</p><p>Enemies’ displayed raw intent damage is reduced by your equipment, then Guard and barriers. Sure Footing adds 8 evasion rating and uses that rating in the enemy’s bounded accuracy check. Enemy glancing hits deal 55% damage. The seal’s 15 barrier applies to its triggering exchange.</p></section><section class="guide-section"><h3>Progress that belongs to you</h3><p>Each of four parts in a level awards one attribute point. Level 10 is this prototype’s cap, at part 1. Free early respecs return all invested points. Equipment never changes your invested budget. Relevant equipped abilities earn at most one mastery mark each per completed eligible encounter, capped at three abilities. Mastery caps at rank 3. At rank 3, Arc Bolt chooses 9 mana or 15% more damage; Brace chooses +15 barrier or a cooldown one exchange shorter; Disrupt chooses +15% damage or one less exchange of interrupt immunity; Mend chooses +15% healing or a cooldown one exchange shorter.</p><p>Enemies 3–5 levels below you award 60% XP; 6 or more below award 25%, with no mastery. Stronger eligible hunts give up to 25% extra XP. First contract completion is awarded once.</p><p>Equipment drops start at 20%. Luck above 8 improves this chance with diminishing returns, approaching 35%. The roll chance is recorded when an encounter starts; duplicates become a salvaged fitting. The Copper-Thread Charm can drop from level 1 onward. The first boss clear gives a guaranteed item choice. Materials are collectible and used at the deterministic workbench for exchanges, gear, upgrades, and prefix/suffix reforges. Each operation shows its cost and result and asks for confirmation before spending. Random rarity tiers remain future work.</p></section><section class="guide-section"><h3>A first chapter, not a persistent world</h3><p>This is a solo, browser-local prototype based on your design pack. Progress is saved on this browser after each action. There is no account sync, multiplayer, server-verified economy, prestige, offline progress, or live AI narrator. B.U.R.S.A.R.’s responses are authored and tied to recorded events.</p><p>The source includes your modular design files. Balance, combined-action costs, enemy numbers, glancing hits and ability unlock requirements are explicit prototype choices for playtesting.</p></section>`;
function guideSections(){let index=0;return RULES.replace(/<section class="guide-section"><h3>(.*?)<\/h3>([\s\S]*?)<\/section>/g,(_,title,body)=>`<details class="guide-section guide-topic" ${index++===0?'open':''}><summary>${icon('guide')}${title}</summary>${body}</details>`);}
function guideView(){return shell(`<div class="guide-page">${recordsTabs()}<div class="guide-tools">${titlePanel('YOUR SAVE',`<h3>Keep your receipts.</h3><p>Export a character to back it up or move devices. Import adds a character and preserves the current roster.</p><div class="save-controls">${btn('export','Export save','subtle')}${btn('import','Import a save','subtle')}</div><p class="tiny muted">Save format v4. Imports v1, v2, v3, and v4.</p>`)}${titlePanel('CHARACTERS',`<p>Keep up to six independent local adventures.</p>${btn('character-manager','Manage characters','subtle')}`)}${titlePanel('PLAYTEST LAB',`<p>Independent disposable characters; no campaign saves are read or changed.</p><a class="lab-launch-link" href="lab.html" target="_blank" rel="noopener">${icon('lab')}Open playtest lab ↗</a>`)}</div>${guideSections()}</div>`,'The fine print, legibly.','Rules, saves, and character management.','FIELD GUIDE · RULES & SAVES');}
function syncCombatDelay(){
clearTimeout(actionDelayTimer);
const controls=$('.combat-controls');if(!controls||!state.fight)return;
const remaining=G.actionDelayRemaining(state),waiting=remaining>0;
controls.classList.toggle('waiting',waiting);
for(const button of controls.querySelectorAll('[data-action^="combat:"]')){
 const key=button.dataset.action.split(':')[1],info=G.actionInfo(state,key);
 button.disabled=waiting||!!info.reason;
 button.title=info.reason||(waiting?'Brief action delay. Tap again when ready.':info.desc);
}
$('#action-ready-text').textContent=waiting?'Action recovery · next tap soon':'Ready for your next action';
$('#action-delay-count').textContent=waiting?(remaining/1000).toFixed(2)+'s':'Ready';
$('#action-delay-track').setAttribute('aria-valuenow',String(Math.max(0,G.ACTION_DELAY_MS-remaining)));
$('#action-delay-track').setAttribute('aria-valuetext',waiting?'Recovering · '+(remaining/1000).toFixed(2)+' seconds remaining':'Ready');
const track=controls.querySelector('.action-delay-track i');
track.style.setProperty('--action-wait',remaining+'ms');
if(waiting)actionDelayTimer=setTimeout(syncCombatDelay,remaining+10);
}
function newCharacterView(){return `<div class="new-character-page"><header class="wizard-brand">${icon('crown')}<span>Crown & Calamity</span><small>v0.8.0 · Bracken Quay</small></header><main class="new-character-content"><div class="eyebrow">A NEW ADVENTURER</div><h1>Who is joining the ledger?</h1><p>Your saved adventures stay on this browser. Choose a name, background, and starter kit to begin.</p><section class="panel character-wizard"><label>Adventurer name<input id="new-name" maxlength="32" placeholder="Your name" autocomplete="given-name"></label><label>Race<select id="new-race"><option>Human</option><option>Stonekin</option></select></label><label>Background<textarea id="new-origin" maxlength="70" rows="2" placeholder="Former canal surveyor">Former canal surveyor</textarea></label><label>Starter kit<select id="new-kit"><option value="bulwark">Bulwark · Inspector’s Rod, shield, Arc Bolt</option><option value="caster">Caster · Inspector’s Rod, focus, Arc Bolt</option><option value="duelist">Duelist · Surveyor’s Blade, charm, Driving Strike</option><option value="breaker">Breaker · Canal-Iron Sword, shield, Driving Strike</option></select></label><p class="wizard-note">Starter kits are equipment and learned abilities, not permanent classes. You begin with 20 coins.</p>${btn('create-character','Create adventurer','primary full-width')}${btn('import','Import an existing save','text-button full-width')}</section></main></div>`;}
function storyView(){return shell(renderStory(state),'The work beneath the Quay','Minor jobs establish the problem. Major contracts change the story.','CHAPTER I · STORY & CONTRACTS');}
function render(){save();$('#app').innerHTML=firstRun?newCharacterView():({hunt:huntView,story:storyView,character:characterView,bag:bagView,market:marketView,journal:journalView,guide:guideView,world:worldView}[view])();syncCombatDelay();}
function modal(title,body,eyebrow='ADVENTURER SERVICES'){const m=$('#modal');m.innerHTML=`<div class="modal-head"><div><div class="eyebrow">${eyebrow}</div><h2 id="modal-title">${title}</h2></div><button data-action="close" class="close" aria-label="Close dialog">${icon('close')}</button></div><div class="modal-body">${body}</div>`;if(!m.open)m.showModal();}
function close(){if($('#modal').open)$('#modal').close();}
function claim(){if(state.pending==='bossLoot'){modal('A choice, duly earned.',`<p>The Superintendent is relieved of duty. Choose one guaranteed first-clear reward. Both can support a build; neither binds your future.</p><div class="choices">${['seal','band'].map(id=>btn('boss-loot:'+id,`<strong>${resolved(id).name}</strong><small>${resolved(id).desc}</small>`,'choice')).join('')}</div>`,'CHAPTER COMPLETE · BELOW THE WATERLINE');return;}view='story';close();render();window.scrollTo({top:0});}

function equipmentEffectPreview(id,targetSlot=null){const item=resolved(id),slot=targetSlot||(G.slotChoices?.(state,id)||[item.slot]).find(x=>!state.gear[x])||(G.slotChoices?.(state,id)||[item.slot])[0];if(!slot)return '';const before=G.totals(state),gear={...state.gear,[slot]:id};for(const [k,v] of Object.entries(gear))if(k!==slot&&v===id)gear[k]=null;if(item.twoHanded)gear.offhand=null;const after=G.totals({...state,gear});const names={hp:'Max health',mp:'Max mana',sp:'Max stamina',armor:'Armor',ward:'Ward',heavyPower:'Heavy power',precisionPower:'Precision power',spellPower:'Spell power',physicalAcc:'Physical accuracy',spellAcc:'Spell accuracy',evasion:'Evasion',critChance:'Critical chance',equipmentDropChance:'Equipment drops'};const changes=Object.entries(names).filter(([key])=>before[key]!==after[key]);return changes.length?`<h3>What changes for your build</h3><div class="equipment-effects">${changes.map(([key,name])=>`<p><strong>${name}</strong><br>${['critChance','equipmentDropChance'].includes(key)?percent(before[key]):before[key]} → ${['critChance','equipmentDropChance'].includes(key)?percent(after[key]):after[key]}</p>`).join('')}</div>`:'';}
function costLedger(cost){const rows=[];if(cost?.coins)rows.push(`Coins: ${state.coins} / ${cost.coins}`);for(const [m,n] of Object.entries(cost?.materials||{}))rows.push(`${m}: ${state.materials?.[m]||0} / ${n}`);return rows.length?`<p class="cost-ledger">On hand · ${rows.map(esc).join(' · ')}</p>`:'';}
function bonusLabels(bonus={}){return [...Object.entries(bonus).filter(([k])=>k!=='stats').map(([k,v])=>`${v} ${k}`),...Object.entries(bonus.stats||{}).map(([k,v])=>`${v} ${G.ATTRS[k]?.[0]||k}`)].join(' · ')||'No listed bonus';}
function previewPair(title,p,confirmAction,eyebrow='WORKBENCH PREVIEW'){const before=p?.before,after=p?.after,price=costLine(p?.cost);modal(title,`<p class="explicit-cost"><strong>Cost to confirm: ${esc(price)}</strong></p>${costLedger(p?.cost)}${costSources(p?.cost)?`<p class="material-hint">Source: ${esc(costSources(p.cost))}</p>`:''}<div class="compare"><div><span class="eyebrow">BEFORE</span>${before?itemArt(before,'large'):''}<h3>${esc(before?.name||'Current item')}</h3><p>${itemStats(before||{}).map(esc).join('<br>')||'No listed bonuses.'}</p></div><div><span class="eyebrow">AFTER</span>${after?itemArt(after,'large'):''}<h3>${esc(after?.name||'Updated item')}</h3><p>${itemStats(after||{}).map(esc).join('<br>')||'No listed bonuses.'}</p></div></div>${p?.reason?`<p class="ability-reason">${esc(p.reason)}</p>`:''}<p class="modal-help">No currency or materials are spent until you confirm below.</p><div class="modal-actions">${btn(confirmAction,'Confirm and spend','primary',!p?.allowed||!!state.fight||!!state.delve)}${btn('close','Cancel','subtle')}</div>`,eyebrow);}
function openExchange(id){const r=G.EXCHANGES?.[id];if(!r)return;const block=exchangeBlock(r),can=exchangeCanAfford(r);modal(r.name,`<div class="exchange-flow"><div><small>YOU GIVE</small><strong>${Object.entries(r.cost||{}).map(([m,n])=>`${n} ${esc(m)}`).join(' + ')}</strong></div><span>→</span><div><small>YOU RECEIVE</small><strong>${esc(exchangeOutput(r))}</strong></div></div><p>Source: ${Object.keys(r.cost||{}).map(m=>esc(MATERIAL_SOURCES[m]||'Hunts and contracts')).join('; ')}</p>${block?`<p class="ability-reason">${esc(block)}</p>`:''}<p class="explicit-cost"><strong>Cost: ${costLine({coins:r.coins,materials:r.cost})}</strong></p>${costLedger({coins:r.coins,materials:r.cost})}<div class="modal-actions">${btn('exchange-confirm:'+id,'Confirm exchange','primary',!can||!!block||!!state.fight||!!state.delve)}${btn('close','Cancel','subtle')}</div>`,'MATERIAL EXCHANGE');}
function openAffixMenu(id,kind){const item=resolved(id),list=kind==='prefix'?G.PREFIXES:G.SUFFIXES;const candidates=Object.values(list||{}).filter(x=>x.slots?.includes(item.slot));modal(`Reforge ${item.name}`,`<p>Choose a ${kind} to preview. An existing ${kind} will be replaced only after you confirm the new cost.</p><div class="affix-options">${candidates.map(x=>{const p=G.affixPreview(state,id,kind,x.id);return `<button data-action="affix-preview:${id}:${kind}:${x.id}" class="affix-option" ${!!state.fight||!!state.delve?'disabled':''}><strong>${esc(x.name)}</strong><small>${bonusLabels(x.bonus)}</small><small>Cost: ${costLine(p.cost)}</small>${costSources(p.cost)?`<small>Source: ${esc(costSources(p.cost))}</small>`:''}${p.reason?`<small>${esc(p.reason)}</small>`:''}</button>`;}).join('')}</div><div class="modal-actions">${btn('close','Back','subtle')}</div>`,'CHOOSE A REFORGE');}
function exportSave(){const b=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(b),a=document.createElement('a');a.href=url;a.download=`crown-calamity-level-${state.level}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Save exported. Keep it somewhere dry.');}
function identity(){modal('Your name on the paperwork.',`<label>Adventurer name<input id="name-input" maxlength="32" value="${esc(state.name)}" autocomplete="off"></label><label>Race<select id="race-input"><option ${state.race==='Human'?'selected':''}>Human</option><option ${state.race==='Stonekin'?'selected':''}>Stonekin</option></select></label><label>Background<input id="origin-input" maxlength="70" value="${esc(state.origin)}"></label><p class="modal-help">Both races share the same attribute budget and ability access. Identity has no portrait.</p><div class="modal-actions">${btn('save-identity','Save identity','primary')}${btn('close','Cancel','subtle')}</div>`);}
async function act(action){const parts=action.split(':'),[a,b,c]=parts,d=parts.slice(3).join(':');if(a==='close'){close();return;}if(a==='social-open'){socialOpen=true;socialTab=['chat','friends','guilds','holdings'].includes(b)?b:'chat';render();$('#social-close')?.focus();return;}if(a==='social-close'){socialOpen=false;render();$('#social-toggle')?.focus();return;}if(a==='social-tab'){if(['chat','friends','guilds','holdings'].includes(b))socialTab=b;render();$('[data-action="social-tab:'+socialTab+'"]')?.focus();return;}if(a==='world-tab'){if(['world','friends','guilds','holdings'].includes(b))worldTab=b;view='world';render();$('[data-action="world-tab:'+worldTab+'"]')?.focus();return;}if(a==='create-character'){const name=$('#new-name').value.trim(),race=$('#new-race').value,origin=$('#new-origin').value.trim()||'Former canal surveyor',kit=$('#new-kit').value;const created=C.createRosterCharacter(roster,{name,race,origin,kit},state);if(!created){toast(roster.characters.length>=C.MAX_CHARACTERS?'All six character slots are in use.':'Choose a valid name, race, background, and starter kit. Character creation is unavailable during a fight or delve.');return;}state=created.state;firstRun=false;view='story';huntTab='hunts';charTab='overview';close();render();window.scrollTo({top:0});return;}if(a==='character-manager'){characterManager();return;}if(a==='new-character-form'){if(roster.characters.length>=C.MAX_CHARACTERS){toast('All six character slots are in use.');return;}newCharacterModal();return;}if(a==='switch-character'){const next=C.switchCharacter(roster,b,state);if(!next){toast(state.fight||state.delve?'Characters cannot be switched during a fight or delve.':'Character could not be switched.');return;}state=next;firstRun=false;view='hunt';huntTab=state.delve?'delve':'hunts';charTab='overview';close();render();toast(`${state.name} is now active.`);return;}if(a==='char-tab'){ charTab=b;render();window.scrollTo({top:0});return;}if(a==='slot'){slotChooser(b);return;}if(a==='slot-select'){compare(b,c);return;}if(a==='open-gear'){view='character';charTab='gear';render();close();window.scrollTo({top:0});return;}if(a==='nav-abilities'){view='character';charTab='abilities';close();render();window.scrollTo({top:0});return;}if(a==='open-shop'){view='market';shopMode='buy';render();close();window.scrollTo({top:0});return;}if(a==='nav'){if(!nav().some(([id])=>id===b))return;view=b;render();window.scrollTo({top:0});return;}if(a==='rest'){if(G.restore(state)){render();toast('Recovered fully at Bracken Quay. No time, coin, or progress required.');}else toast('Recovery at the Quay is available outside combat and expeditions.');return;}
if(a==='story-accept'){if(G.acceptContract(state,b)){render();toast('Contract accepted. Your objectives now track completed actions.');}else toast('This contract is not available yet, or you are in an encounter.');return;}
if(a==='story-action'){const receipt=G.storyAction(state,b);if(receipt){render();modal('At the lower stair',`<p>${esc(receipt.text)}</p><div class="modal-actions">${btn('close','Continue','primary')}</div>`,'BELOW THE WATERLINE');}else toast('Complete the listed objective before taking this story step.');return;}
if(a==='story-claim'){const receipt=G.claimContract(state,b,c);if(receipt){render();toast(`${G.STORY_CONTRACTS[b].kind==='major'?'Story milestone':'Minor contract'} completed · +${receipt.xp} XP · +${receipt.coins} coins.`);}else toast('This contract is not ready to report.');return;}
if(a==='story-delve'){view='hunt';huntTab='delve';state.last=null;render();window.scrollTo({top:0});return;}
if(a==='hunt'){if(state.delve){toast('Finish or leave the delve before hunting.');return;}if(G.startFight(state,b)){view='hunt';huntTab='hunts';render();window.scrollTo({top:0});}else toast(state.hp<=0?'Recover at the Quay before setting out.':'This hunt is not available yet.');return;}
if(a==='combat'){const before=state.discoveries.length;const result=G.exchange(state,b);if(!result.ok){toast(result.reason);return;}render();if(state.discoveries.length>before)toast('Interaction discovered: Stored Pressure. Recorded in your Chronicle.');if(result.victory||result.defeat||result.withdraw)window.scrollTo({top:0});return;}
if(a==='toggle-log'){state.settings.details=!state.settings.details;render();return;}if(a==='mechanics'){modal('Every action, accounted for.',`<p>Attack is free. Cast spends 12 mana. Wardcast trades spell damage for Guard (12 mana, 8 stamina). Defend is free. Each tap resolves just this exchange. A shared 0.65-second delay follows accepted actions. Extra taps during that pause are ignored, not queued.</p><p>Recover restores 15 mana / 20 stamina; the enemy still acts. Brace, Disrupt, and Mend show remaining cooldown exchanges on their buttons. A blocked action spends no turn.</p><p>Reservoir needs Guard to prevent at least 20 damage. It stores one +10% spell charge for the next exchange only.</p><div class="modal-actions">${btn('close','Back to the encounter','primary')}${btn('open-guide','All the rules →','subtle')}</div>`,'COMBAT REFERENCE');return;}
if(a==='open-guide'){close();view='guide';render();window.scrollTo({top:0});return;}if(a==='tab'){huntTab=b;state.last=null;render();return;}if(a==='clear-outcome'){state.last=null;render();return;}if(a==='delve-show'){state.last=null;huntTab='delve';render();return;}if(a==='delve-start'){if(G.startDelve(state)){huntTab='delve';render();}return;}if(a==='delve'){if(G.delveAction(state,b)){state.last=null;render();window.scrollTo({top:0});if(b==='rest')toast('Camp used. Resources fully restored.');}return;}if(a==='delve-leave'){modal('Return to town?',`<p>Your completed room rewards stay yours. This run ends, and its camp and rooms reset on your next entry.</p><div class="modal-actions">${btn('confirm-leave','Return to the Quay','primary')}${btn('close','Stay in the works','subtle')}</div>`);return;}if(a==='confirm-leave'){G.delveAction(state,'leave');close();render();return;}
if(a==='claim'){claim();return;}if(a==='quest'){if(G.completeQuest(state,b)){close();render();toast('Contract completed. Rewards and your choice recorded.');}return;}if(a==='boss-loot'){if(G.chooseBossLoot(state,b)){close();render();toast(`${resolved(b).name} added to your satchel.`);}return;}
if(a==='stat'){if(G.allocate(state,b)){render();}return;}if(a==='kit'){if(G.practice(state,b)){render();toast('Owned starter gear and its matching skill are prepared. Your attributes stay yours.');}return;}if(a==='passive'){if(G.equipAbility(state,b)){render();toast('Passive equipped.');}else toast(G.abilityStatus(state,b)?.reason||'Passive cannot be equipped.');return;}
if(a==='ability-learn'){if(G.learnAbility(state,b)){render();toast(`${G.ABILITIES[b].name} learned.`);}else toast(G.abilityStatus(state,b)?.reason||'Requirements are not met.');return;}if(a==='ability-equip'){if(G.equipAbility(state,b)){render();toast(`${G.ABILITIES[b].name} equipped.`);}else toast(G.abilityStatus(state,b)?.reason||'Ability cannot be equipped.');return;}if(a==='ability-remove'){if(G.unequipAbility(state,b)){render();toast(G.ABILITIES[b].kind==='passive'?`${G.ABILITIES[b].name} removed from the passive slot.`:`${G.ABILITIES[b].name} removed from the active bar.`);}return;}if(a==='mastery'){if(G.chooseMastery(state,b,c)){render();toast('Mastery choice recorded.');}return;}if(a==='identity'){identity();return;}if(a==='save-identity'){if(state.fight||state.delve)return;const n=$('#name-input').value.trim();if(!n){$('#name-input').focus();toast('Your name cannot be blank.');return;}state.name=n.slice(0,32);state.race=$('#race-input').value;state.origin=$('#origin-input').value.trim().slice(0,70)||'Adventurer of Bracken Quay';close();render();return;}
if(a==='respec'){modal('Reconsider your unreasonable choices.',`<p>Return all invested attributes to 8 and reclaim ${earnedAttributeBudget(state)-56} points to allocate. Equipment and learned mastery stay yours. Current resources will be capped to your revised limits.</p><div class="modal-actions">${btn('confirm-respec','Reallocate for free','primary')}${btn('close','Keep this build','subtle')}</div>`,'FREE EARLY RESPEC');return;}if(a==='confirm-respec'){if(G.resetStats(state)){close();render();}return;}
if(a==='shop-luck'){view='market';vendorId='curio';shopMode='buy';render();window.scrollTo({top:0});return;}if(a==='bag-tab'){if(b==='shop'){view='market';shopMode='buy';}else{view='bag';bagTab=b;}render();return;}if(a==='vendor'){if(M.VENDORS[b]){vendorId=b;render();}return;}if(a==='market-compare'){marketCompare(b,c);return;}if(a==='shop-tab'){if(['buy','sell'].includes(b))shopMode=b;render();return;}if(a==='compare'){compare(b);return;}if(a==='equip'){if(G.equip(state,b,c)){close();render();toast(`${resolved(b).name} equipped in ${SLOT_LABELS[c||resolved(b).slot]||c||resolved(b).slot}.`);}return;}if(a==='unequip-slot'){if(G.unequip(state,b)){render();toast(`${SLOT_LABELS[b]||b} slot emptied.`);}return;}if(a==='exchange'){openExchange(b);return;}if(a==='exchange-confirm'){const r=G.exchangeMaterials(state,b);if(r){close();render();toast(r.gainedItems?.length?`${r.gainedItems.map(id=>resolved(id)?.name||id).join(', ')} added to your satchel.`:'Materials exchanged. The receipt is in your satchel.');}else toast('Exchange unavailable: check the listed materials and coins.');return;}if(a==='upgrade'){const p=G.upgradePreview(state,b);previewPair(`Upgrade ${resolved(b).name}`,p,'upgrade-confirm:'+b);return;}if(a==='upgrade-confirm'){if(G.upgradeItem(state,b)){close();render();toast(`${resolved(b).name} upgraded.`);}return;}if(a==='affix-menu'){openAffixMenu(b,c);return;}if(a==='affix-preview'){const p=G.affixPreview(state,b,c,d);previewPair(`Apply ${G[c==='prefix'?'PREFIXES':'SUFFIXES']?.[d]?.name||'affix'}`,p,`affix-confirm:${b}:${c}:${d}`,'REFORGE PREVIEW');return;}if(a==='affix-confirm'){if(G.applyAffix(state,b,c,d)){close();render();toast(`${resolved(b).name} reforged.`);}return;}if(a==='buy-preview'){buyReview(b);return;}if(a==='buy-confirm'){if(G.buy(state,b)){close();render();toast(`${resolved(b).name} added to your satchel. Compare it before equipping.`);}else toast(G.buyPreview(state,b)?.reason||'Purchase unavailable.');return;}if(a==='sell-preview'){sellReview(b);return;}if(a==='sell-confirm'){const itemName=resolved(b)?.name||'Item',receipt=G.sell(state,b);if(receipt){close();render();toast(`${itemName} sold for ${receipt.coins} coins.`);}else toast(G.sellPreview(state,b)?.reason||'Sale unavailable.');return;}
if(a==='export'){exportSave();return;}if(a==='import'){modal('Add an adventure to your roster.',`<p>This save will be added as a new character. Your current character and roster stay saved. You can keep up to ${C.MAX_CHARACTERS} characters on this browser.</p><input id="save-file" class="file-input" type="file" accept="application/json,.json" aria-label="Choose save file"><div class="modal-actions">${btn('confirm-import','Import as new character','primary',roster.characters.length>=C.MAX_CHARACTERS||!!state.fight||!!state.delve)}${btn('close','Cancel','subtle')}</div>${roster.characters.length>=C.MAX_CHARACTERS?'<p class="ability-reason">All character slots are in use.</p>':''}`,'SAVE MANAGEMENT');return;}
if(a==='confirm-import'){const f=$('#save-file').files[0];if(!f){toast('Choose a save file first.');return;}if(f.size>2e6){toast('That file is too large to be a save.');return;}const created=C.importRosterCharacter(roster,await f.text(),state);if(!created){toast(roster.characters.length>=C.MAX_CHARACTERS?'All six character slots are in use.':'This save could not be imported right now.');return;}state=created.state;firstRun=false;close();view='hunt';charTab='overview';huntTab=state.delve?'delve':'hunts';render();toast('Save imported as a new character. Your previous adventures remain in the roster.');return;}
if(a==='reset'){characterManager();return;}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b&&!b.disabled){try{Promise.resolve(act(b.dataset.action)).catch(err=>{console.error(err);toast('That action could not be completed. Your last saved progress is safe.');});}catch(err){console.error(err);toast('That action could not be completed.');}}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&socialOpen){e.preventDefault();act('social-close');return;}if(e.repeat&&e.target.closest('[data-action^="combat:"]'))e.preventDefault();});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close();}});
document.addEventListener('change',e=>{if(e.target.id==='inspect-target'&&G.ENEMIES.some(x=>x.id===e.target.value)){state.settings.inspectTarget=e.target.value;render();$('#inspect-target')?.focus();}});
if(state.delve)huntTab='delve';render();
